ARCH_PRELUDE = """
/* Architecture-dependent values for Darwin. */
#if defined(__LP64__) || defined(__arm64__)
#  define SIZEOF_LONG 8
#  define SIZEOF_SIZE_T 8
#  define SIZEOF_PTHREAD_T 8
#  define SIZEOF_PTHREAD_KEY_T 8
#  define ALIGNOF_LONG 8
#  define ALIGNOF_SIZE_T 8
#else
#  define SIZEOF_LONG 4
#  define SIZEOF_SIZE_T 4
#  define SIZEOF_PTHREAD_T 4
#  define SIZEOF_PTHREAD_KEY_T 4
#  define ALIGNOF_LONG 4
#  define ALIGNOF_SIZE_T 4
#endif

#define ALIGNOF_MAX_ALIGN_T 16

#if defined(__arm64__)
#  define SIZEOF_LONG_DOUBLE 8
#else
#  define SIZEOF_LONG_DOUBLE 16
#endif

#if defined(__x86_64__)
#  define HAVE_GCC_ASM_FOR_X64 1
#endif
"""


def parse_defines():
    result = []
    for line in DEFINES.strip().splitlines():
        parts = line.split(None, 1)
        if len(parts) == 1:
            result.append((parts[0], "1"))
        else:
            result.append((parts[0], parts[1]))
    return result


def main():
    if len(sys.argv) != 3:
        sys.exit("usage: generate_pyconfig.py IN OUT")

    with open(sys.argv[1], "r", encoding="utf-8") as infile:
        lines = infile.readlines()

    body = []
    for line in lines:
        match = re.match(r"#undef\s+(\w+)", line)
        if match:
            body.append("/* #undef %s */\n" % match.group(1))
        else:
            body.append(line)

    header = ["/* Generated for the Darling CPython 3 cross-build. Do not edit. */\n"]
    header.append(ARCH_PRELUDE)
    for name, value in parse_defines():
        header.append("#define %s %s\n" % (name, value))
    header.append("\n")

    with open(sys.argv[2], "w", encoding="utf-8") as outfile:
        outfile.writelines(header)
        outfile.writelines(body)


if __name__ == "__main__":
    main()
